def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -np.abs(remaining - 0.5), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -np.fmod(remaining, 1.0), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.1 * bins
    score = -np.abs(remaining - target_buffer)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    optimal_utilization = 0.9
    score = -((utilization - optimal_utilization) ** 2)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    target = 0.85
    score = -np.exp(np.abs(utilization - target))
    return np.where(remaining >= 0, score, -np.inf)
